cases.actual_sql:
SELECT name, state, population
FROM public.city
WHERE population BETWEEN 1000000 AND 2000000;

SELECT id, name, state, population, year, source
FROM public.city
ORDER BY population ASC;

SELECT c.id, c.name, c.state, c.population, c.year
FROM public.city c
WHERE c.population > (
    SELECT AVG(population) FROM public.city
);

SELECT id, name, state, population, year, source
FROM public.city
WHERE name LIKE '%San%';

SELECT name, state, population, year
FROM public.city
WHERE population = (SELECT MAX(population) FROM public.city);

SELECT name, state
FROM public.city
WHERE population > 1500000;

SELECT DISTINCT c.name
FROM public.city c
JOIN public.salary s ON c.id = s.city_id;
